<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(403);exit;}
function request_areas(string $text): array {
 return array_values(array_unique(array_filter(array_map('trim',preg_split('/[\\r\\n·•]+/u',$text)?:[]),fn($area)=>$area!=='')));
}
function request_progress(): void {
 echo '<nav class="booking-progress" aria-label="Booking progress"><ol><li aria-current="step">1<span>Service</span></li><li>2<span>Details</span></li><li>3<span>Schedule</span></li><li>4<span>Contact</span></li><li>5<span>Review</span></li></ol></nav>';
}
function request_form(string $slug,array $row,string $error,bool $sent): void {
 $key=$slug.':booking';$ticket=enquiry_ticket($key);
 if($_SERVER['REQUEST_METHOD']==='GET'||!isset($_SESSION['forms'][$key]['snapshot']))$_SESSION['forms'][$key]['snapshot']=['services'=>$row['services'],'zone'=>$row['time_zone'],'areas'=>request_areas((string)($row['document']['areas']??''))];
 $catalogue=$_SESSION['forms'][$key]['snapshot']['services'];$zone=$_SESSION['forms'][$key]['snapshot']['zone'];
 $value=fn($k)=>esc(is_string($_POST[$k]??null)?$_POST[$k]:'');
 echo '<section class="public-card" id="booking" aria-label="Booking request">';
 if($error)echo '<p class="alert" role="alert">'.esc($error).'</p>';
 if($sent)echo '<p class="notice" role="status">Request received — pending confirmation. This is not a confirmed booking. The business will review your request.</p>';
 echo '<div class="request-layout"><form id="booking-request" method="post" action="'.esc(cfg()['base_url'].'/b/'.$slug.'?booking=1').'#booking"><input type="hidden" name="snapshot_hash" value="'.esc(hash('sha256',json_encode($_SESSION['forms'][$key]['snapshot'],JSON_THROW_ON_ERROR))).'"><input type="hidden" name="csrf" value="'.esc($ticket['csrf']).'"><div class="spam-field" aria-hidden="true"><label for="website">Leave blank</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><p id="step-status" class="step-status" aria-live="polite" hidden></p><fieldset data-step="0"><legend>Service</legend><p class="service-intro">Choose a service</p><div class="booking-services">';
 foreach($catalogue['items']??[] as $s)if($s['visible']&&!$s['archived']){
  $price=$s['mode']==='quote'?'Quote required':services_price($s,$catalogue['currency']);
  $icon=str_contains(strtolower($s['name']),'office')?'<path d="M8 27V7h16v20M5 27h22M12 11h2m4 0h2m-8 5h2m4 0h2m-8 5h2m4 0h2"/>':(str_contains(strtolower($s['name']),'deep')?'<path d="m16 3 3.5 9.5L29 16l-9.5 3.5L16 29l-3.5-9.5L3 16l9.5-3.5ZM26 3v6m-3-3h6"/>':'<path d="m4 15 12-10 12 10M8 13v15h16V13M13 28v-9h6v9"/>');
  echo '<label class="booking-service-card"><input type="radio" name="service" value="'.esc($s['id']).'" data-name="'.esc($s['name']).'" data-price="'.esc($price).'" required'.(($_POST['service']??'')===$s['id']?' checked':'').'><span class="service-card-icon" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'.$icon.'</svg></span><span class="service-card-name">'.esc($s['name']).'</span> ';

  echo '</label>';
 }
 echo '<script type="application/json" id="booking-catalogue">'.json_encode($catalogue,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script><script type="application/json" id="booking-selections">'.json_encode(is_array($_POST['options']??null)?$_POST['options']:new stdClass(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script>';
 echo '<noscript><button name="configure_options" value="1" formnovalidate>Show selected service options</button><p>Choose your service, then show its options before sending.</p></noscript>';
 echo '</div><p id="selected-price" class="service-selected-price" hidden>Choose a service</p>';
 echo '</fieldset><fieldset data-step="1"><legend>Details</legend><div class="booking-details-content"><div class="address-entry"><h2>Where do you need help?</h2><label for="address">Street address</label><div class="address-input-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg><input id="address" name="address" type="text" autocomplete="address-line1" placeholder="Street number, street name, suburb and city" aria-describedby="address-help" required minlength="5" maxlength="1000" value="'.$value('address').'"></div><small id="address-help">Enter the full address where the service is needed.</small><label for="unit" class="unit-label">Unit / apartment number and name <span>(Optional)</span></label><input id="unit" name="unit" type="text" autocomplete="address-line2" placeholder="e.g. Unit 2A, Building name" maxlength="120" value="'.$value('unit').'"></div><div id="booking-options">'.request_options_fallback($catalogue).'</div><label for="requirements">Notes or instructions (optional)</label><textarea id="requirements" name="requirements" rows="4" maxlength="1900">'.$value('requirements').'</textarea>';
 $areas=$_SESSION['forms'][$key]['snapshot']['areas']??[];
 if($areas){echo '<div class="coverage-note"><label for="service-area">Service area</label><select id="service-area" name="service_area" data-faraios-select required><option value="">Select service area</option>';foreach($areas as $area)echo '<option value="'.esc($area).'"'.(($_POST['service_area']??'')===$area?' selected':'').'>'.esc($area).'</option>';echo '</select></div><small>The business will confirm whether your address is covered.</small>';}
 echo '</div></fieldset><fieldset data-step="2"><legend>Schedule</legend><div class="booking-schedule-content"><div class="schedule-entry"><h2>When do you need help?</h2><label for="date">Preferred date</label><input id="date" name="date" type="date" data-faraios-picker min="'.esc((new DateTimeImmutable('now',new DateTimeZone($zone)))->format('Y-m-d')).'" max="2099-12-31" required value="'.$value('date').'"><label for="time">Preferred time</label><input id="time" name="time" type="time" data-faraios-picker required value="'.$value('time').'"><small>Business time zone: '.esc($zone).'. Preferred time only; no availability reservation.</small></div></div></fieldset><fieldset data-step="3"><legend>Contact</legend><div class="booking-contact-content"><div class="contact-entry"><h2>How can we reach you?</h2>';
 foreach(['name'=>['Your name','text','name',120],'email'=>['Email address','email','email',254],'phone'=>['Phone number','tel','tel',40]] as $k=>[$label,$type,$auto,$max])echo '<label for="'.$k.'">'.$label.'</label><input id="'.$k.'" name="'.$k.'" type="'.$type.'" autocomplete="'.$auto.'" maxlength="'.$max.'" '.($k==='name'?'required minlength="2"':'').' value="'.$value($k).'">';

 echo '<small>Provide an email address or phone number.</small></div></div></fieldset><fieldset data-step="4"><legend>Review</legend><div class="booking-review-content"><div class="review-entry"><h2>Review your request</h2><p class="review-intro">Check the details before sending.</p><section class="review-price-section" aria-label="Price breakdown"><h3>Price breakdown</h3><div id="review-breakdown"></div><div class="review-total"><span id="review-total-label">Estimated total</span><strong data-review="price"></strong></div><small>Estimated duration: <span id="review-duration"></span></small></section><div id="booking-review"><section class="review-section"><div class="review-section-heading"><h3>Service</h3><button type="button" data-summary-edit="0" aria-label="Edit reviewed service">Edit</button></div><p data-review="service"></p><p class="review-secondary" data-review="options"></p></section><section class="review-section"><div class="review-section-heading"><h3>Location</h3><button type="button" data-summary-edit="1" aria-label="Edit reviewed address">Edit</button></div><p data-review="address"></p><p class="review-secondary" data-review="area"></p></section><section class="review-section"><div class="review-section-heading"><h3>Schedule</h3><button type="button" data-summary-edit="2" aria-label="Edit reviewed schedule">Edit</button></div><p id="review-schedule"></p><small>'.esc($zone).' · Preferred time</small></section><section class="review-section"><div class="review-section-heading"><h3>Contact</h3><button type="button" data-summary-edit="3" aria-label="Edit reviewed contact">Edit</button></div><p data-review="name"></p><p class="review-secondary" data-review="email"></p><p class="review-secondary" data-review="phone"></p></section><section class="review-section" id="review-notes-section"><div class="review-section-heading"><h3>Notes or instructions</h3><button type="button" data-summary-edit="1" aria-label="Edit reviewed notes">Edit</button></div><p data-review="requirements"></p></section></div><div class="review-confirmation"><strong>Pending confirmation</strong><p>The business will confirm your request and preferred time. No payment is taken now.</p></div></div></div></fieldset><p class="review-privacy request-privacy">Your details are shared privately with '.esc($row['document']['name']??'this business').' to handle your request. <a href="'.esc(cfg()['base_url']).'/privacy.html#bookings" target="_blank" rel="noopener noreferrer" aria-label="Booking privacy notice (opens in a new tab)">How your booking details are used</a></p><div class="booking-controls"><button type="button" id="booking-back" hidden>Back</button><button type="button" class="button" id="booking-continue" hidden>Continue</button><button type="submit" class="button" id="booking-send">Send booking request</button></div></form><aside class="request-summary" aria-label="Booking summary"><details class="summary-shell" open><summary>Booking details <span id="summary-price">Choose a service</span></summary><div class="summary-rows"><button type="button" class="summary-row" data-summary-edit="1" id="summary-where-row" hidden aria-label="Edit service address"><span class="summary-row-copy"><span class="summary-label">Where</span><span id="summary-address"></span><small id="summary-area"></small></span><span class="summary-edit" aria-hidden="true">✎</span></button><button type="button" class="summary-row" data-summary-edit="0" id="summary-what-row" hidden aria-label="Edit service"><span class="summary-row-copy"><span class="summary-label">What</span><span id="summary-service"></span><small id="summary-options"></small></span><span class="summary-edit" aria-hidden="true">✎</span></button><button type="button" class="summary-row" data-summary-edit="2" id="summary-when-row" hidden aria-label="Edit preferred schedule"><span class="summary-row-copy"><span class="summary-label">When</span><span id="summary-schedule"></span></span><span class="summary-edit" aria-hidden="true">✎</span></button></div><div class="summary-cost-bar"><span>Total: <strong id="summary-total">Choose a service</strong></span><button type="button" id="summary-cost-toggle" aria-expanded="false" aria-controls="summary-cost-details">Costs</button></div><div id="summary-cost-details" hidden><h3>Price breakdown</h3><p id="summary-breakdown"></p><p>Estimated duration: <span id="summary-duration"></span></p></div><p class="summary-notice">Pending confirmation · No payment now.</p><span id="summary-zone" hidden>'.esc($zone).'</span></details></aside></div></section>';
}
function request_submit(string $slug,array $row): void {
 $key=$slug.':booking';$ticket=enquiry_ticket($key);$snapshot=$ticket['snapshot']??null;
 $origin=parse_url(cfg()['base_url'],PHP_URL_SCHEME).'://'.parse_url(cfg()['base_url'],PHP_URL_HOST);if($port=parse_url(cfg()['base_url'],PHP_URL_PORT))$origin.=':'.$port;
 if((int)($_SERVER['CONTENT_LENGTH']??0)>20000||!is_string($_POST['csrf']??null)||!hash_equals($ticket['csrf'],$_POST['csrf'])||(isset($_SERVER['HTTP_ORIGIN'])&&$_SERVER['HTTP_ORIGIN']!==$origin)||($_SERVER['HTTP_SEC_FETCH_SITE']??'')==='cross-site'||!$snapshot)throw new RuntimeException('This form has expired. Reload before submitting.');
 if(!is_string($_POST['snapshot_hash']??null)||!hash_equals(hash('sha256',json_encode($snapshot,JSON_THROW_ON_ERROR)),$_POST['snapshot_hash']))throw new RuntimeException('Service, price or time zone changed. Reload before submitting.');
 if(($_POST['website']??'')!==''||time()-$ticket['time']<2)throw new RuntimeException('Please wait a moment and try again.');
 $areas=request_areas((string)($row['document']['areas']??''));if(($snapshot['areas']??[])!==$areas)throw new RuntimeException('Service areas changed. Reload before submitting.');
 $area=enquiry_text('service_area',0,2000);if(($areas&&!in_array($area,$areas,true))||(!$areas&&$area!==''))throw new RuntimeException('Choose a configured service area.');
 $name=enquiry_text('name',2,120);$email=strtolower(enquiry_text('email',0,254));$phone=enquiry_text('phone',0,40);$requirements=enquiry_text('requirements',0,1900);$address=enquiry_text('address',5,1000);
 if(preg_match('/[\r\n\t]/',$name))throw new RuntimeException('Check your name.');
 if($email===''&&$phone==='')throw new RuntimeException('Enter an email address or phone number.');
 if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');
 if($phone!==''&&(!preg_match('/\A[+0-9 ()-]{5,40}\z/',$phone)||strlen(preg_replace('/\D/','',$phone))<5))throw new RuntimeException('Enter a valid phone number.');
 $unit=enquiry_text('unit',0,120);if($unit!=='')$address.=', '.$unit;if(mb_len($address)>1000)throw new RuntimeException('Keep the full service address within 1000 characters.');
 $service=enquiry_text('service',1,32);$s=null;foreach($snapshot['services']['items'] as $item)if($item['id']===$service&&$item['visible']&&!$item['archived'])$s=$item;if(!$s)throw new RuntimeException('Choose an available service.');
 $date=enquiry_text('date',10,10);$time=enquiry_text('time',5,5);$local=$date.' '.$time;$dt=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$local,new DateTimeZone('UTC'));if(!$dt||$dt->format('Y-m-d H:i')!==$local)throw new RuntimeException('Choose a valid preferred schedule.');
 $selected=$_POST['options']??[];if(!is_array($selected)||count($selected)>19)throw new RuntimeException('Check room and extra selections.');$selections=[];foreach($selected as $oid=>$qty){if(!is_string($oid)||!preg_match('/\A[a-f0-9]{32}\z/',$oid)||!is_string($qty)||!preg_match('/\A[0-9]{1,4}\z/',$qty))throw new RuntimeException('Check room and extra quantities.');$selections[]=['id'=>$oid,'quantity'=>(int)$qty];}
 $requirements=$requirements!==''?'Notes or instructions: '.$requirements:'No additional instructions.';
 if($area!=='')$requirements='Service area: '.$area."\n\n".$requirements;if(mb_len($requirements)>2000)throw new RuntimeException('Shorten your notes or instructions to fit the selected service area.');
 enquiry_ip_limit();api('/rest/v1/rpc/business_booking_request_submit',['p_environment'=>profile_env(),'p_slug'=>$slug,'p_service'=>$service,'p_name'=>$name,'p_email'=>$email,'p_phone'=>$phone,'p_requirements'=>$requirements,'p_request'=>$ticket['request'],'p_address'=>$address,'p_local'=>$local.':00','p_zone'=>$snapshot['zone'],'p_currency'=>$snapshot['services']['currency'],'p_service_snapshot'=>$s,'p_selections'=>$selections]);
 unset($_SESSION['forms'][$key]);$_SESSION['booking_request_sent']=$slug;header('Location: '.cfg()['base_url'].'/b/'.rawurlencode($slug).'?booking=1#booking',true,303);exit;
}

function request_options_fallback(array $catalogue): string {
 $html='';foreach($catalogue['items'] as $service)if($service['id']===($_POST['service']??'')){
 foreach($service['options']??[] as $o){$q=$_POST['options'][$o['id']]??max($o['minimum'],$o['included']);$html.='<label for="fallback-'.$o['id'].'">'.esc($o['name']).'</label><input id="fallback-'.$o['id'].'" name="options['.$o['id'].']" type="number" required min="'.$o['minimum'].'" max="'.$o['maximum'].'" step="1" value="'.esc(is_string($q)||is_int($q)?(string)$q:'').'"><small>'.(int)$o['included'].' included · +'.esc(services_price(['mode'=>'fixed','amount'=>$o['price']],$catalogue['currency'])).' per additional unit · +'.(int)$o['minutes'].' minutes</small>';}
 }return $html;
}
